    P <= 131071 ->
    getr regs 2 = spm -> getr regs 4 = Z_to_bv 64 0x65d4b0 -> getr regs 18 = pp ->
    lzok RSEGS L S Zr (mkCfg msF mo) -> same_but_materialized mo0 mo ->
    restrict L S msF = mkst regs (Z_to_bv 64 0xa2f60) mem0 (seg_rom RSEGS) ->
